function countClearingStarts(nums: number[]): number {
  let good = 0;
  for (let s = 0; s < nums.length; s++) {
    if (nums[s] !== 0) continue;
    for (const dir of [-1, 1]) {
      const a = nums.slice();
      let cur = s, d = dir;
      while (cur >= 0 && cur < a.length) {
        if (a[cur] > 0) {
          a[cur]--;
          d = -d;
        }
        cur += d;
      }
      if (a.every(v => v === 0)) good++;
    }
  }
  return good;
}

