class Solution:
    def countClearingStarts(self, nums: List[int]) -> int:
        good = 0
        for s, v in enumerate(nums):
            if v != 0:
                continue
            for d0 in (-1, 1):
                a = nums[:]
                cur, d = s, d0
                while 0 <= cur < len(a):
                    if a[cur] > 0:
                        a[cur] -= 1
                        d = -d
                    cur += d
                if not any(a):
                    good += 1
        return good

