function countClearingStarts(nums: number[]): number {
  const total = nums.reduce((a, b) => a + b, 0);
  let left = 0, good = 0;
  for (const v of nums) {
    if (v === 0) {
      const right = total - left;
      if (left === right) good += 2;
      else if (Math.abs(left - right) === 1) good += 1;
    }
    left += v;
  }
  return good;
}

